import React, { Component } from 'react';

class EventCreationForm extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      inspectors: [''],
      participants: [{ name: '', iin: '' }]
    };
  }

  handleAddInspector = () => {
    this.setState(prevState => ({
      inspectors: [...prevState.inspectors, '']
    }));
  };

  handleAddParticipant = () => {
    this.setState(prevState => ({
      participants: [...prevState.participants, { name: '', iin: '' }]
    }));
  };

  render() {
    const { inspectors, participants } = this.state;

    return (
      <div className="form-container">
        <div className="sidebar">
          <h2>Система учета посещаемости</h2>
          <nav>
            <ul>
              <li>Создание мероприятия</li>
              <li>Список созданных мероприятий</li>
              <li>Профиль</li>
              <li>Выход</li>
            </ul>
          </nav>
        </div>
        <div className="form-content">
          <h1>Создание мероприятия</h1>
          <form>
            <label>Название мероприятия</label>
            <input type="text" placeholder="Напишите название мероприятия" />

            <label>Тип мероприятия</label>
            <select>
              <option value="">Выберите тип мероприятия</option>
              <option value="seminar">Семинар</option>
              <option value="workshop">Мастер-класс</option>
              <option value="conference">Конференция</option>
            </select>

            <label>Дата проведения</label>
            <input type="date" />

            <label>Добавьте проверяющего(-их)</label>
            {inspectors.map((inspector, index) => (
              <div key={index} className="inspector-input">
                <input type="email" placeholder="Введите почту проверяющего" />
              </div>
            ))}
            <button type="button" className="add-button" onClick={this.handleAddInspector}>
              Добавить проверяющего
            </button>

            <label>Добавьте участника(-ов)</label>
            {participants.map((participant, index) => (
              <div key={index} className="participant-input">
                <label>Участник №{index + 1}</label>
                <input type="text" placeholder="Введите ФИО участника" />
                <input type="text" placeholder="Введите ИИН участника" />
              </div>
            ))}
            <button type="button" className="add-button" onClick={this.handleAddParticipant}>
              Добавить участника
            </button>

            <button type="submit" className="create-button">
              Создать
            </button>
          </form>
        </div>
      </div>
    );
  }
}

export default EventCreationForm;
